// src/api/clienteApi.js
import axios from 'axios';

// Base URL do seu servidor backend Spring Boot
const BASE_URL = 'http://localhost:8080/clientes';

// Função para obter todos os clientes
export const obterClientes = async () => {
  try {
    const response = await axios.get(BASE_URL);
    return response.data; // Retorna a lista de clientes
  } catch (error) {
    console.error('Erro ao obter clientes:', error);
    throw error;
  }
};


export const criarCliente = async (cliente) => {
  try {
    const response = await axios.post(BASE_URL, cliente);
    return response.data;
  } catch (error) {
    console.error('Erro ao criar cliente:', error);
    throw error;
  }
};

